package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api/catalog") public class CatalogController{private final JdbcClient db;public CatalogController(JdbcClient db){this.db=db;}
 public record Item(UUID id,String name,String description,String type,BigDecimal price,Integer durationMonths,String badge,String category,String flavour,String unitLabel,String preparationOptions,String allergenNote,boolean featured,boolean imageAvailable,String catalogGroup){}
 public record Manage(UUID id,@Pattern(regexp="PRODUCT|SERVICE|PACKAGE")String type,@NotBlank String name,String description,@DecimalMin("0")BigDecimal price,@Min(1)Integer durationMonths,boolean active,List<UUID> includedItemIds,String category,String flavour,String unitLabel,String preparationOptions,String allergenNote,boolean featured,@Pattern(regexp="CAKE|GENERAL")String catalogGroup){}
 @GetMapping List<Item> list(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);return db.sql("select id,name,description,type,price,duration_months,null::varchar badge,category,flavour,unit_label,preparation_options,allergen_note,featured,(image_data is not null) image_available,catalog_group from amcservice.catalog_items where tenant_id=:t and active union all select id,name,description,'PACKAGE',price,duration_months,case when duration_months=12 then 'Popular care plan' end,null,null,'package',null,null,false,false,'GENERAL' from amcservice.packages where tenant_id=:t and active order by type,name").param("t",u.tenantId()).query(Item.class).list();}
 @GetMapping("/manage") @PreAuthorize("hasAnyRole('OWNER','ADMIN','SALESPERSON')") List<Map<String,Object>> manage(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);var rows=new ArrayList<Map<String,Object>>();rows.addAll(db.sql("select id,type,name,description,price,duration_months,active,category,flavour,unit_label,preparation_options,allergen_note,featured,catalog_group,(image_data is not null) image_available,created_at from amcservice.catalog_items where tenant_id=:t order by type,name").param("t",u.tenantId()).query().listOfRows());for(var row:db.sql("select id,'PACKAGE' type,name,description,price,duration_months,active,'GENERAL' catalog_group,created_at from amcservice.packages where tenant_id=:t order by name").param("t",u.tenantId()).query().listOfRows()){var copy=new LinkedHashMap<String,Object>(row);copy.put("included_item_ids",db.sql("select catalog_item_id from amcservice.package_items where package_id=:p order by catalog_item_id").param("p",row.get("id")).query(UUID.class).list());rows.add(copy);}return rows;}
 @PostMapping @PreAuthorize("hasAnyRole('OWNER','ADMIN','SALESPERSON')") @ResponseStatus(HttpStatus.CREATED) @Transactional Map<String,Object> create(@AuthenticationPrincipal CurrentUser u,@Valid@RequestBody Manage r){CustomerController.tenant(u);var id=UUID.randomUUID();save(u,id,r,true);return Map.of("id",id);}
 @PutMapping("/{id}") @PreAuthorize("hasAnyRole('OWNER','ADMIN','SALESPERSON')") @Transactional void update(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@Valid@RequestBody Manage r){CustomerController.tenant(u);save(u,id,r,false);}
 @PostMapping(value="/{id}/image",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasAnyRole('OWNER','ADMIN','SALESPERSON')") void image(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@RequestPart("file")MultipartFile file)throws Exception{CustomerController.tenant(u);if(file.isEmpty()||file.getSize()>2_000_000||file.getContentType()==null||!file.getContentType().startsWith("image/"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an image up to 2 MB");if(db.sql("update amcservice.catalog_items set image_file_name=:n,image_content_type=:c,image_data=:d where id=:id and tenant_id=:t").param("n",file.getOriginalFilename()).param("c",file.getContentType()).param("d",file.getBytes()).param("id",id).param("t",u.tenantId()).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Catalog item not found");}
 @GetMapping("/{id}/image") ResponseEntity<byte[]> image(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id){CustomerController.tenant(u);var row=db.sql("select image_content_type,image_data from amcservice.catalog_items where id=:id and tenant_id=:t and image_data is not null").param("id",id).param("t",u.tenantId()).query().listOfRows().stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));return ResponseEntity.ok().contentType(MediaType.parseMediaType(String.valueOf(row.get("image_content_type")))).cacheControl(CacheControl.noCache()).body((byte[])row.get("image_data"));}
 private void save(CurrentUser u,UUID id,Manage r,boolean create){if("PACKAGE".equals(r.type())){savePackage(u,id,r,create);return;}String unit=r.unitLabel()==null||r.unitLabel().isBlank()?"item":r.unitLabel(),group=r.catalogGroup()==null?"GENERAL":r.catalogGroup();if(create)db.sql("insert into amcservice.catalog_items(id,tenant_id,type,name,description,price,duration_months,active,category,flavour,unit_label,preparation_options,allergen_note,featured,catalog_group) values(:id,:t,:type,:name,:description,:price,:months,:active,:category,:flavour,:unit,:prep,:allergen,:featured,:group)").param("id",id).param("t",u.tenantId()).param("type",r.type()).param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",r.durationMonths()).param("active",r.active()).param("category",r.category()).param("flavour",r.flavour()).param("unit",unit).param("prep",r.preparationOptions()).param("allergen",r.allergenNote()).param("featured",r.featured()).param("group",group).update();else if(db.sql("update amcservice.catalog_items set type=:type,name=:name,description=:description,price=:price,duration_months=:months,active=:active,category=:category,flavour=:flavour,unit_label=:unit,preparation_options=:prep,allergen_note=:allergen,featured=:featured,catalog_group=:group where id=:id and tenant_id=:t").param("type",r.type()).param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",r.durationMonths()).param("active",r.active()).param("category",r.category()).param("flavour",r.flavour()).param("unit",unit).param("prep",r.preparationOptions()).param("allergen",r.allergenNote()).param("featured",r.featured()).param("group",group).param("id",id).param("t",u.tenantId()).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Catalog item not found");}
 private void savePackage(CurrentUser u,UUID id,Manage r,boolean create){int months=r.durationMonths()==null?1:r.durationMonths();if(create)db.sql("insert into amcservice.packages(id,tenant_id,name,description,price,duration_months,active) values(:id,:t,:name,:description,:price,:months,:active)").param("id",id).param("t",u.tenantId()).param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",months).param("active",r.active()).update();else if(db.sql("update amcservice.packages set name=:name,description=:description,price=:price,duration_months=:months,active=:active where id=:id and tenant_id=:t").param("name",r.name()).param("description",r.description()).param("price",r.price()).param("months",months).param("active",r.active()).param("id",id).param("t",u.tenantId()).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Package not found");db.sql("delete from amcservice.package_items where package_id=:id").param("id",id).update();for(var item:Optional.ofNullable(r.includedItemIds()).orElse(List.of()))db.sql("insert into amcservice.package_items(package_id,catalog_item_id,quantity) select :p,id,1 from amcservice.catalog_items where id=:i and tenant_id=:t").param("p",id).param("i",item).param("t",u.tenantId()).update();}
}
